    15	export interface InstrumentOptions {
    16	  /** Required: this server's logical name. Not derivable from the McpServer instance (its `serverInfo` is private), so it's an explicit option. */
    17	  serverName: string;
    18	  serverVersion?: string;
    19	  sinks: Sink[];
    20	  /** Opt-in: capture tool arguments at all. Default false — no arguments are ever recorded unless this is true. */
    21	  captureArguments?: boolean;
    22	  redaction?: RedactionConfig;
    23	  /** Opt-in: inject session_id/agent_id/intent into advertised tool schemas. Default false (off for every tool). */
    24	  intentCapture?: IntentCaptureOption;
    25	  /** Host-supplied user/org identity. The library never infers these itself. */
    26	  resolveIdentity?: (ctx: {
    27	    sessionId?: string;
    28	  }) =>
    29	    | { userId?: string; orgId?: string }
    30	    | undefined
    31	    | Promise<{ userId?: string; orgId?: string } | undefined>;
    32	  bufferSize?: number;
    33	  /** Pass `null` for manual mode: no interval timer, no `beforeExit` listener — flush explicitly via the returned handle's `flush()`. */
    34	  flushIntervalMs?: number | null;
    35	}
