    37	/**
    38	 * Returned by `instrument()`. `server` is the same instance passed in
    39	 * (instrumentation mutates it in place); use the handle's `server` rather
    40	 * than your own pre-instrument reference so a future non-mutating
    41	 * implementation doesn't silently drop instrumentation under you.
    42	 */
    43	export interface InstrumentHandle {
    44	  server: McpServer;
    45	  /** Flushes any buffered events immediately. On a request-scoped runtime (e.g. Cloudflare Workers), call this via `ctx.waitUntil(handle.flush())` before returning the response. */
    46	  flush(): Promise<void>;
    47	}
    48	
    49	interface ToolCallContext {
    50	  sessionId?: string;
    51	  http?: unknown;
    52	}
    53	
    54	interface ToolResultLike {
    55	  content?: Array<{ type: string; text?: string }>;
    56	  isError?: boolean;
    57	}
    58	
    59	function byteLength(value: unknown): number {
    60	  return Buffer.byteLength(JSON.stringify(value) ?? '');
    61	}
    62	
    63	function extractErrorMessage(result: ToolResultLike): string | null {
    64	  const text = (result.content ?? [])
    65	    .filter(
    66	      (block): block is { type: 'text'; text: string } =>
    67	        block.type === 'text' && typeof block.text === 'string'
    68	    )
    69	    .map(block => block.text)
    70	    .join(' ');
    71	  if (!text) return null;
    72	  return text.length > 2000 ? text.slice(0, 2000) : text;
    73	}
