    75	/**
    76	 * Wraps an `McpServer` so every tool registered through it (after this call)
    77	 * records a `tool_call` event. This is the library's one required call —
    78	 * call it immediately after constructing the server and before registering
    79	 * any tools, since it works by wrapping `registerTool` itself.
    80	 *
    81	 * A failure inside a sink or the buffer is caught and never propagates to
    82	 * the tool handler or delays its response — see EventBuffer. A thrown error
    83	 * from the real tool handler is re-thrown unchanged; this wrapper only
    84	 * observes it.
    85	 */
    86	export function instrument(server: McpServer, options: InstrumentOptions): InstrumentHandle {
    87	  const buffer = new EventBuffer({
    88	    sinks: options.sinks,
    89	    bufferSize: options.bufferSize,
    90	    flushIntervalMs: options.flushIntervalMs
    91	  });
    92	
    93	  const originalRegisterTool = server.registerTool.bind(server);
    94	
    95	  server.registerTool = ((
    96	    name: string,
    97	    config: Record<string, unknown>,
    98	    cb: (...args: unknown[]) => unknown
    99	  ) => {
   100	    const intentEnabled = isIntentCaptureEnabled(options.intentCapture, name);
   101	    const originalInputSchema = config.inputSchema;
   102	    const canInject = intentEnabled && schemaSupportsInjection(originalInputSchema);
   103	
   104	    const wrappedConfig = canInject
   105	      ? { ...config, inputSchema: injectIntentSchema(originalInputSchema) }
   106	      : config;
   107	
   108	    const wrappedCb = async (args: Record<string, unknown>, ctx: ToolCallContext) => {
   109	      const startedAt = new Date();
   110	      const start = performance.now();
   111	
   112	      const requestBytes = byteLength(args);
   113	
   114	      let cleanArgs = args;
   115	      let sessionIdFromArgs: string | null = null;
   116	      let agentId: string | null = null;
   117	      let intent: string | null = null;
   118	      if (canInject) {
   119	        const extracted = extractAndStripIntent(args);
   120	        cleanArgs = extracted.clean;
   121	        sessionIdFromArgs = extracted.session_id;
   122	        agentId = extracted.agent_id;
   123	        intent = extracted.intent;
   124	      }
   125	
   126	      const sessionId = ctx.sessionId ?? sessionIdFromArgs ?? null;
   127	      const identity = (await options.resolveIdentity?.({ sessionId: ctx.sessionId })) ?? {};
   128	      // getClientVersion() is deprecated in favor of reading client identity off the
   129	      // per-request `_meta` envelope, but the SDK's own deprecation note says the accessor
   130	      // "remains functional" and is backfilled per request on 2026-07-28-era connections too.
   131	      // Deliberately kept rather than reaching into the envelope's internal shape, which isn't
   132	      // part of this SDK's stable public surface yet.
   133	      const clientInfo = server.server.getClientVersion();
   134	
   135	      const emit = (
   136	        partial: Pick<ToolCallEvent, 'success' | 'error_kind' | 'error_message' | 'response_bytes'>
   137	      ) => {
   138	        buffer.push({
   139	          event_type: 'tool_call',
   140	          ts: startedAt,
   141	          server_name: options.serverName,
   142	          server_version: options.serverVersion ?? null,
   143	          tool_name: name,
   144	          session_id: sessionId,
   145	          agent_id: agentId,
   146	          client_name: clientInfo?.name ?? null,
   147	          client_version: clientInfo?.version ?? null,
   148	          user_id: identity.userId ?? null,
   149	          org_id: identity.orgId ?? null,
   150	          duration_ms: Math.round(performance.now() - start),
   151	          request_bytes: requestBytes,
   152	          arguments: applyRedaction(cleanArgs, options.redaction, options.captureArguments),
   153	          intent,
   154	          transport: ctx.http ? 'http' : 'stdio',
   155	          ...partial
   156	        });
   157	      };
   158	
   159	      try {
   160	        const result = (await cb(cleanArgs, ctx)) as ToolResultLike;
   161	        if (result?.isError) {
   162	          const errorMessage = extractErrorMessage(result);
   163	          emit({
   164	            success: false,
   165	            error_kind: classifyError(errorMessage),
   166	            error_message: errorMessage,
   167	            response_bytes: byteLength(result)
   168	          });
   169	        } else {
   170	          emit({
   171	            success: true,
   172	            error_kind: null,
   173	            error_message: null,
   174	            response_bytes: byteLength(result)
   175	          });
   176	        }
   177	        return result;
   178	      } catch (error) {
   179	        const message = error instanceof Error ? error.message : String(error);
   180	        const truncated = message.length > 2000 ? message.slice(0, 2000) : message;
   181	        emit({
   182	          success: false,
   183	          error_kind: classifyError(truncated),
   184	          error_message: truncated,
   185	          response_bytes: 0
   186	        });
   187	        throw error;
   188	      }
   189	    };
   190	
   191	    // The real `registerTool` overloads are exact per input/output schema shape; a
   192	    // generic wrapper can't preserve that precision through a monkey-patch, so we
   193	    // widen to `any` at this one call site rather than fighting the overload set.
   194	    return (originalRegisterTool as (...args: unknown[]) => unknown)(
   195	      name,
   196	      wrappedConfig,
   197	      wrappedCb
   198	    );
   199	  }) as typeof server.registerTool;
   200	
   201	  return { server, flush: () => buffer.flush() };
   202	}
