     4	export interface EventBufferOptions {
     5	  sinks: Sink[];
     6	  bufferSize?: number;
     7	  /**
     8	   * Flush interval in ms. Pass `null` to disable the interval timer (and the
     9	   * `beforeExit` listener) entirely — manual mode, for request-scoped
    10	   * runtimes like Cloudflare Workers where a timer isn't guaranteed to fire
    11	   * again before the isolate is evicted. In manual mode the caller is
    12	   * responsible for calling `flush()` explicitly before the request ends
    13	   * (e.g. `ctx.waitUntil(buffer.flush())`). Default: 5000.
    14	   */
    15	  flushIntervalMs?: number | null;
    16	}
    17	
    18	const DEFAULT_BUFFER_SIZE = 20;
    19	const DEFAULT_FLUSH_INTERVAL_MS = 5000;
    20	
    21	/**
    22	 * Batches events and flushes on a size threshold or an interval, whichever
    23	 * comes first, plus a best-effort flush on process shutdown. A sink whose
    24	 * `write` throws or rejects is caught and logged at most once per sink
    25	 * instance — it never propagates to the caller, and never blocks the other
    26	 * sinks (all sinks are written in parallel via `allSettled`). Pass
    27	 * `flushIntervalMs: null` for manual mode: no timer, no `beforeExit`
    28	 * listener, the caller flushes explicitly.
    29	 */
    30	export class EventBuffer {
    31	  private readonly sinks: Sink[];
    32	  private readonly bufferSize: number;
    33	  private queue: AnyEvent[] = [];
    34	  private readonly warned = new WeakSet<Sink>();
    35	  private readonly timer?: NodeJS.Timeout;
    36	  // Chains every flush's write so `flush()` always waits for the ones ahead
    37	  // of it, not just for its own batch. Without this, the size-triggered
    38	  // `void this.flush()` in `push()` is fire-and-forget: a caller who awaits
    39	  // a *later* `flush()` call (e.g. `ctx.waitUntil(handle.flush())` on
    40	  // Workers, right before returning the response) can see an already-empty
    41	  // queue and resolve immediately, while the earlier batch's sink write is
    42	  // still in flight — on an isolate-based runtime that write can then be cut
    43	  // off before it lands. Chaining onto `pending` makes every `flush()` call
    44	  // resolve only once every write started before it has settled.
    45	  private pending: Promise<void> = Promise.resolve();
    46	  private readonly onBeforeExit = () => {
    47	    void this.flush();
    48	  };
    49	
    50	  constructor(options: EventBufferOptions) {
    51	    this.sinks = options.sinks;
    52	    this.bufferSize = options.bufferSize ?? DEFAULT_BUFFER_SIZE;
    53	    const manual = options.flushIntervalMs === null;
    54	
    55	    if (!manual) {
    56	      const flushIntervalMs = options.flushIntervalMs ?? DEFAULT_FLUSH_INTERVAL_MS;
    57	
    58	      this.timer = setInterval(() => {
    59	        void this.flush();
    60	      }, flushIntervalMs);
    61	      this.timer.unref?.();
    62	
    63	      process.on('beforeExit', this.onBeforeExit);
    64	    }
    65	  }
    66	
    67	  push(event: AnyEvent): void {
    68	    this.queue.push(event);
    69	    if (this.queue.length >= this.bufferSize) {
    70	      void this.flush();
    71	    }
    72	  }
    73	
    74	  flush(): Promise<void> {
    75	    if (this.queue.length === 0) return this.pending;
    76	    const batch = this.queue;
    77	    this.queue = [];
    78	
    79	    const write = this.writeBatch(batch);
    80	    this.pending = this.pending.then(() => write);
    81	    return this.pending;
    82	  }
    83	
    84	  private async writeBatch(batch: AnyEvent[]): Promise<void> {
    85	    await Promise.allSettled(
    86	      this.sinks.map(async sink => {
    87	        try {
    88	          await sink.write(batch);
    89	        } catch (error) {
    90	          if (!this.warned.has(sink)) {
    91	            this.warned.add(sink);
    92	            console.error(
    93	              '[mcpsignals] sink failed, further errors from this sink are suppressed:',
    94	              error
    95	            );
    96	          }
    97	        }
    98	      })
    99	    );
   100	  }
   101	
   102	  stop(): void {
   103	    clearInterval(this.timer);
   104	    process.off('beforeExit', this.onBeforeExit);
   105	  }
   106	}
