     3	/**
     4	 * Best-effort heuristic over free-text error messages. Not a structured
     5	 * code — `success` is the ground truth for pass/fail. See schema/events.md
     6	 * for the documented false-positive mode.
     7	 */
     8	export function classifyError(message: string | undefined | null): ErrorKind | null {
     9	  if (!message) return null;
    10	
    11	  if (/not found|does not exist|no such/i.test(message)) return 'not_found';
    12	  if (/\bempty\b|no results?|nothing found|zero results/i.test(message)) return 'empty';
    13	  if (/invalid|required|expected|must be|validation|schema/i.test(message)) return 'validation';
    14	  return 'internal';
    15	}
