    17	const INTENT_FIELDS = {
    18	  session_id: z.string().optional().describe('Groups this call with others in the same task.'),
    19	  agent_id: z
    20	    .string()
    21	    .optional()
    22	    .describe('Distinguishes this agent from others running in parallel.'),
    23	  intent: z.string().optional().describe('Why you are calling this tool.')
    24	};
    25	
    26	/**
    27	 * Extends a tool's input schema with optional session_id/agent_id/intent
    28	 * fields so the client can see and populate them. Handles a full Zod object
    29	 * schema (`.extend()`), a raw shape record (plain object merge, the legacy
    30	 * `registerTool` form), and no schema at all (a fresh object schema with
    31	 * just the three injected fields). Returns the input unchanged for any other
    32	 * Standard Schema (e.g. Valibot/ArkType) — injection is skipped rather than
    33	 * risking a crash on a schema shape this library doesn't understand; the
    34	 * caller should treat that as "intent capture unavailable for this tool."
    35	 */
    36	export function injectIntentSchema<T>(inputSchema: T): T {
    37	  if (inputSchema === undefined) {
    38	    return z.object(INTENT_FIELDS) as unknown as T;
    39	  }
    40	  if (inputSchema instanceof z.ZodObject) {
    41	    return inputSchema.extend(INTENT_FIELDS) as unknown as T;
    42	  }
    43	  if (
    44	    typeof inputSchema === 'object' &&
    45	    inputSchema !== null &&
    46	    Object.values(inputSchema as Record<string, unknown>).every(v => v instanceof z.ZodType)
    47	  ) {
    48	    return { ...(inputSchema as Record<string, unknown>), ...INTENT_FIELDS } as unknown as T;
    49	  }
    50	  return inputSchema;
    51	}
    52	
    53	/** True if `injectIntentSchema` actually added the injected fields for this input. */
    54	export function schemaSupportsInjection(inputSchema: unknown): boolean {
    55	  if (inputSchema === undefined) return true;
    56	  if (inputSchema instanceof z.ZodObject) return true;
    57	  return (
    58	    typeof inputSchema === 'object' &&
    59	    inputSchema !== null &&
    60	    Object.values(inputSchema as Record<string, unknown>).every(v => v instanceof z.ZodType)
    61	  );
    62	}
    63	
    64	/**
    65	 * Length caps on the three values the calling agent supplies. Without them
    66	 * these are the only unbounded caller-controlled strings on an event, and a
    67	 * sink that batches writes in a transaction (Cloudflare D1's `batch()`, for
    68	 * one) loses every unrelated event in the flush when one oversized value
    69	 * fails its statement. Capping here rather than in each sink means every
    70	 * sink, including third-party and future ones, inherits the bound.
    71	 *
    72	 * `intent` is prose and takes the same 2000 as `error_message`.
    73	 * `session_id`/`agent_id` are identifiers - a UUID is 36 chars - so they take
    74	 * a much tighter cap. Oversized values are truncated rather than dropped:
    75	 * losing the tail of an id is cheaper than losing the event.
    76	 */
    77	export const MAX_INTENT_LENGTH = 2000;
    78	export const MAX_IDENTIFIER_LENGTH = 128;
    79	
    80	function boundedString(value: unknown, maxLength: number): string | null {
    81	  if (typeof value !== 'string') return null;
    82	  if (value.length <= maxLength) return value;
    83	  // slice() counts UTF-16 code units, so a naive cut at maxLength can land
    84	  // between the two units of a surrogate pair (e.g. an emoji) and leave a
    85	  // lone surrogate in the result - invalid UTF-16 that some UTF-8 encoders
    86	  // (e.g. node-postgres) reject outright, which would make the value fail
    87	  // the very sink write this bound exists to protect. Back the cut off by
    88	  // one unit when it would split a pair.
    89	  let end = maxLength;
    90	  const code = value.charCodeAt(end - 1);
    91	  if (code >= 0xd800 && code <= 0xdbff) end -= 1;
    92	  return value.slice(0, end);
    93	}
