     9	
    10	function typeOnly(value: unknown): { __type: string } {
    11	  return { __type: value === null ? 'null' : Array.isArray(value) ? 'array' : typeof value };
    12	}
    13	
    14	/**
    15	 * Argument capture is opt-in (`captureArguments`). When on with no redaction
    16	 * config, only key names and value *types* are recorded — never values. Real
    17	 * values are recorded only for keys explicitly named in `allow`.
    18	 */
    19	export function applyRedaction(
    20	  args: Record<string, unknown>,
    21	  config: RedactionConfig | undefined,
    22	  captureArguments: boolean | undefined
    23	): Record<string, unknown> | null {
    24	  if (!captureArguments) return null;
    25	
    26	  if (config?.redactor) {
    27	    return config.redactor(args);
    28	  }
    29	
    30	  const allow = config?.allow;
    31	  const deny = config?.deny ?? [];
    32	
    33	  const result: Record<string, unknown> = {};
    34	  for (const [key, value] of Object.entries(args)) {
    35	    const allowed = allow !== undefined && allow.includes(key) && !deny.includes(key);
    36	    result[key] = allowed ? value : typeOnly(value);
    37	  }
    38	  return result;
    39	}

