     3	
     4	/**
     5	 * Emits one span per `tool_call` event via the global OpenTelemetry
     6	 * TracerProvider — this sink does not manage its own exporter, it relies on
     7	 * whatever the host application already configured (the standard OTel
     8	 * zero-code pattern). Requires the optional peer dependency
     9	 * `@opentelemetry/api` only (not an SDK or exporter).
    10	 *
    11	 * Attribute mapping verified against the live `open-telemetry/semantic-
    12	 * conventions-genai` repo (docs/gen-ai/mcp.md) as of this writing. Every
    13	 * `gen_ai.*` / `mcp.*` attribute below is marked Development, not Stable —
    14	 * expect these names to still move. Fields with no defined MCP/GenAI
    15	 * convention are emitted as custom `mcpsignals.*` attributes rather than
    16	 * forced into a semantically mismatched Stable attribute (see schema/
    17	 * events.md's OTLP mapping note for the `transport` case specifically).
    18	 * `session_summary` events have no span shape defined by the convention and
    19	 * are not emitted by this sink.
    20	 */
    21	export function otlpSink(): Sink {
    22	  return {
    23	    async write(events: AnyEvent[]): Promise<void> {
    24	      const otel = await import('@opentelemetry/api');
    25	      const tracer = otel.trace.getTracer('mcpsignals');
    26	
    27	      for (const event of events) {
    28	        if (event.event_type !== 'tool_call') continue;
    29	
    30	        const span = tracer.startSpan(`tools/call ${event.tool_name}`, {
    31	          kind: otel.SpanKind.SERVER,
    32	          startTime: event.ts,
    33	          attributes: {
    34	            'gen_ai.operation.name': 'execute_tool',
    35	            'gen_ai.tool.name': event.tool_name,
    36	            ...(event.session_id !== null && { 'mcp.session.id': event.session_id }),
    37	            ...(event.arguments !== null && {
    38	              'gen_ai.tool.call.arguments': JSON.stringify(event.arguments)
    39	            }),
    40	            ...(event.intent !== null && { 'mcpsignals.intent': event.intent }),
    41	            ...(event.agent_id !== null && { 'mcpsignals.agent.id': event.agent_id }),
    42	            ...(event.user_id !== null && { 'enduser.id': event.user_id }),
    43	            ...(event.org_id !== null && { 'mcpsignals.org.id': event.org_id }),
    44	            'mcpsignals.server.name': event.server_name,
    45	            ...(event.server_version !== null && {
    46	              'mcpsignals.server.version': event.server_version
    47	            }),
    48	            ...(event.client_name !== null && { 'mcpsignals.client.name': event.client_name }),
    49	            ...(event.client_version !== null && {
    50	              'mcpsignals.client.version': event.client_version
    51	            }),
    52	            ...(event.transport !== null && { 'mcpsignals.transport': event.transport }),
    53	            'mcpsignals.request.bytes': event.request_bytes,
    54	            'mcpsignals.response.bytes': event.response_bytes,
    55	            ...(event.error_kind !== null && { 'mcpsignals.error.kind': event.error_kind })
    56	          }
    57	        });
    58	
    59	        if (!event.success) {
    60	          span.setAttribute('error.type', 'tool_error');
    61	          span.setStatus({
    62	            code: otel.SpanStatusCode.ERROR,
    63	            message: event.error_message ?? undefined
    64	          });
    65	          if (event.error_message) {
    66	            span.addEvent('exception', { 'exception.message': event.error_message });
    67	          }
    68	        } else {
    69	          span.setStatus({ code: otel.SpanStatusCode.OK });
    70	        }
    71	
    72	        const endTime = new Date(event.ts.getTime() + event.duration_ms);
    73	        span.end(endTime);
    74	      }
    75	    }
    76	  };
    77	}

