  4	
  5	/**
  6	 * Builds an instrumented McpServer (not yet connected) plus the events
  7	 * recorded by a capturing sink. The v2 SDK requires every tool to be
  8	 * registered before `connect()` is called ("Cannot register capabilities
  9	 * after connecting to transport") — so callers register their tools on the
 10	 * returned `server`, then call `connectClient(server)` to get a live Client
 11	 * wired to it over an in-memory transport.
 12	 */
 13	export function createInstrumentedServer(instrumentOptions = {}) {
 14	  const events = [];
 15	  const capturingSink = { write: async batch => void events.push(...batch) };
 16	
 17	  const server = new McpServer({ name: 'test-server', version: '1.0.0' });
 18	  const handle = instrument(server, {
 19	    serverName: 'test-server',
 20	    serverVersion: '1.0.0',
 21	    sinks: [capturingSink],
 22	    bufferSize: 1, // flush immediately after every call, so tests don't need to wait
 23	    ...instrumentOptions
 24	  });
 25	
 26	  return { server, events, flush: handle.flush };
 27	}
