 29	export async function connectClient(server) {
 30	  const client = new Client({ name: 'test-client', version: '9.9.9' });
 31	  const [serverTransport, clientTransport] = InMemoryTransport.createLinkedPair();
 32	  await Promise.all([server.connect(serverTransport), client.connect(clientTransport)]);
 33	  return client;
 34	}
